import flask

def test_edge_cases():
    """Test various edge cases for blueprint names"""

    test_cases = [
        ("", "empty string"),
        ("   ", "spaces only"),
        ("\t", "tab only"),
        ("\n", "newline only"),
        ("\r", "carriage return only"),
        (" \t\n\r ", "mixed whitespace"),
        ("test", "normal name"),
        ("test_blueprint", "name with underscore"),
        ("test-blueprint", "name with dash"),
        ("test123", "name with numbers"),
        ("Test", "name with capital letter"),
        ("a", "single character"),
    ]

    for name, description in test_cases:
        try:
            bp = flask.Blueprint(name, __name__)
            print(f"✓ {description}: '{name}' - Created successfully")
        except ValueError as e:
            print(f"✗ {description}: '{name}' - ValueError: {e}")
        except Exception as e:
            print(f"? {description}: '{name}' - Unexpected error: {type(e).__name__}: {e}")

def test_dotted_names():
    """Test that dotted names still raise the correct error"""

    dotted_test_cases = [
        ("app.ui", "simple dotted name"),
        ("my.app.ui", "multiple dots"),
        (".test", "leading dot"),
        ("test.", "trailing dot"),
    ]

    print("\nTesting dotted names (should still raise dot error):")
    for name, description in dotted_test_cases:
        try:
            bp = flask.Blueprint(name, __name__)
            print(f"✗ {description}: '{name}' - Created successfully (should fail)")
        except ValueError as e:
            if "dot" in str(e):
                print(f"✓ {description}: '{name}' - Correct dot error: {e}")
            elif "empty" in str(e):
                print(f"? {description}: '{name}' - Got empty error instead of dot error: {e}")
            else:
                print(f"? {description}: '{name}' - Unexpected ValueError: {e}")
        except Exception as e:
            print(f"? {description}: '{name}' - Unexpected error: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_edge_cases()
    test_dotted_names()"}

