import flask

def test_error_messages():
    """Test that error messages are clear and helpful"""

    # Test empty name error message
    try:
        flask.Blueprint("", __name__)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        assert str(e) == "'name' may not be empty."
        print(f"✓ Empty name error message: {e}")

    # Test whitespace name error message
    try:
        flask.Blueprint("   ", __name__)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        assert str(e) == "'name' may not be empty."
        print(f"✓ Whitespace name error message: {e}")

    # Test dotted name error message (existing functionality)
    try:
        flask.Blueprint("app.ui", __name__)
        assert False, "Should have raised ValueError"
    except ValueError as e:
        assert str(e) == "'name' may not contain a dot '.' character."
        print(f"✓ Dotted name error message: {e}")

    print("✓ All error messages are clear and helpful")

if __name__ == "__main__":
