"""Debug script to understand stream detection."""

from requests.utils import super_len
from requests.compat import basestring

def debug_stream_detection():
    """Debug how stream detection works."""

    test_data = [
        None,
        [],
        {},
        '',
        'string',
        {'key': 'value'},
        [('key', 'value')],
    ]

    for data in test_data:
        try:
            has_iter = hasattr(data, '__iter__')
            not_basestring = not isinstance(data, basestring)
            not_dict = not isinstance(data, dict)
            is_stream = all([has_iter, not_basestring, not_dict])

            try:
                length = str(super_len(data))
            except (TypeError, AttributeError):
                length = False

            print(f"data={repr(data):20} | iter={has_iter} | !str={not_basestring} | !dict={not_dict} | stream={is_stream} | len={length}")
        except Exception as e:
            print(f"data={repr(data):20} | ERROR: {e}")

if __name__ == "__main__":
    debug_stream_detection()"}
